type I18nContextValue = { locale: Locale; theme: Theme; setLocale: (locale: Locale) => void; setTheme: (theme: Theme) => void; t: (key: string, values?: Record<string, string | number>) => string };
const I18nContext = createContext<I18nContextValue | null>(null);
const localeKey = "bundesliga-locale";
const themeKey = "bundesliga-theme";

export function I18nProvider({children}:{children:React.ReactNode}) {
  const [locale,setLocaleState] = useState<Locale>("en");
  const [theme,setThemeState] = useState<Theme>("light");
  useEffect(()=>{
    const storedLocale=window.localStorage.getItem(localeKey) as Locale | null;
    const storedTheme=window.localStorage.getItem(themeKey) as Theme | null;
    if(storedLocale && messages[storedLocale]) setLocaleState(storedLocale);
    if(storedTheme === "light" || storedTheme === "dark") setThemeState(storedTheme);
    else if(storedTheme === "system") window.localStorage.setItem(themeKey,"light");
  },[]);
  useEffect(()=>{
    document.documentElement.dataset.theme=theme; document.documentElement.lang=locale;
  },[theme,locale]);
  const value=useMemo<I18nContextValue>(()=>({locale,theme,setLocale:(next)=>{setLocaleState(next);window.localStorage.setItem(localeKey,next);},setTheme:(next)=>{setThemeState(next);window.localStorage.setItem(themeKey,next);},t:(key,values)=>{let result=messages[locale][key]??messages.en[key]??key; for(const [name,value] of Object.entries(values??{})) result=result.replaceAll(`{${name}}`,String(value)); return result;}}),[locale,theme]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}
export function useI18n(){const context=useContext(I18nContext); if(!context) throw new Error("useI18n must be used within I18nProvider"); return context;}

