// All translation values cross this boundary as UTF-8. A small number of older
// entries were persisted after being decoded as Latin-1; repair those values
// once, before they can reach a rendered component.
function repairLegacyUtf8(value:string):string {
  const legacyPairs:Array<[string,string]>=[["Ãœ","Ü"],["Ã„","Ä"],["Ã–","Ö"],["Ã¤","ä"],["Ã¶","ö"],["Ã¼","ü"],["ÃŸ","ß"],["ÃŽ","Î"],["Ã¢","â"],["Ã®","î"],["Äƒ","ă"],["Ä‚","Ă"],["È˜","Ș"],["È™","ș"],["È›","ț"],["Ē","Ă"],["ē","ă"],["PânĂ","Până"],["â€“","–"],["â€”","—"],["â€¦","…"],["Â·","·"]];
  let result=value;
  for(const [from,to] of legacyPairs) result=result.split(from).join(to);
  for(let attempt=0;attempt<2 && /(?:Ã|Â|â€|ï¿½)/.test(result);attempt++) {
    try {
      const bytes=Uint8Array.from(result,character=>character.charCodeAt(0)&255);
      const decoded=new TextDecoder("utf-8",{fatal:true}).decode(bytes);
      if(decoded===result) break;
      result=decoded;
    } catch { break; }
  }
  return result.replace(/\uFFFD/g,"");
}
for(const locale of ["en","de","es","ro"] as Locale[]) for(const key of Object.keys(messages[locale])) messages[locale][key]=repairLegacyUtf8(messages[locale][key]);

