// Apply the same legacy replacements after every dictionary extension as well;
// later feature-specific dictionaries must not reintroduce old encodings.
for(const locale of ["en","de","es","ro"] as Locale[]) {
  for(const [key,value] of Object.entries(messages[locale])) {
    let fixed=value;
    for(const [from,to] of (legacyTextFixes[locale]??[])) fixed=fixed.split(from).join(to);
    messages[locale][key]=repairLegacyUtf8(fixed)
      .replace(/\u0003/g,"ă").replace(/\u001b/g,"ș").replace(/\u0018/g,"Ș").replace(/\u0019/g,"ș");
  }
}

